const DOMAIN_LYT: DomainSchema = {
  domain: "yai.lyt",
  version: "1.0",
  status: "active",
  tier: "official",
  verified: true,
  score: 1,
  notice: null,
  description: "The YON domain for Lyt federated-vault storage. Defines the record families that Lyt vaults, meshes, and pods emit as their YON-as-source-of-truth. Ledger (@AUDIT / @PROVENANCE / @ROTATION) captures per-vault append-only audit, provenance, and month-rotation events. Mesh (@MESH / @MESH_HOME / @MESH_EDGE / @MESH_SUBSCRIPTION) declares a vault federation's identity — its push target, home vaults, edges, and subscriptions. Federation (@FEDERATION / @FED_MESH / @FED_AUTOMATOR / @FED_PRIMER / @FED_CANVAS) describes a pod's joined meshes, registered automators, and primer + canvas pointers. Lane (@LANE / @LANE_MEMBER) clusters figments by shared tag frequency into a per-vault search layer. Arc (@ARC / @ARC_MEMBER) orders figments into position-ordered narrative sequences. Vault-home-mesh (@VAULT_HOME_MESH) is a per-vault declaration of its owning mesh. Public-mesh (@MESH_PUBLIC / @UPDATE_CADENCE) carries publisher-declared discovery metadata and sync cadence for meshes advertised publicly.",
  defaultMode: "struct",
  defaultProfile: "audit",
  defaultFormat: "canon",
  records: {
    AUDIT: {
      description: "Append-only audit log entry — every Lyt vault action that touches state (init, mesh-init, automator write, friction note, rebuild-index, …) emits one @AUDIT record to the vault's audit.yon ledger, followed by a chained @STAMP.",
      requiredFields: ["ts", "actor", "action", "target_type", "target_id"],
      optionalFields: ["result", "details_json"],
      typedFields: { "ts": "ts" },
      fields: {
        "ts": { type: "ts", required: true, description: "ISO 8601 UTC timestamp the audited action took place", example: "2026-05-30T14:30:00.000Z" },
        "actor": { type: "string", required: true, description: "Who performed the action — user:<handle>, automator:<name>/<ver>, agent:<name>, or system:lyt", example: "user:acme-handler" },
        "action": { type: "string", required: true, description: "Action verb — typically '<surface>.<verb>' (e.g. vault.init, mesh.add-edge, automator.write, friction.note, rebuild.ledger)", example: "automator.write" },
        "target_type": { type: "string", required: true, description: "Kind of entity the action operated on — vault, mesh, edge, subscription, provenance, note, declaration, registry, etc.", example: "provenance" },
        "target_id": { type: "string", required: true, description: "Identifier of the targeted entity — rid string, vault-relative path, or natural-key identifier", example: "notes/2026-05-30-thought-yai-lyt.md" },
        "result": { type: "string", required: false, enum: ["success", "failure", "skipped", "partial"], description: "Outcome of the action — defaults to 'success' when omitted", example: "success" },
        "details_json": { type: "string", required: false, description: "JSON-encoded extra context. Common keys: target_path, target_kind, run_id_hex, mesh_rid, fields_changed", example: "{\"target_path\":\"notes/x.md\",\"target_kind\":\"note\",\"run_id_hex\":\"01a2…\"}" },
      },
    },
    PROVENANCE: {
      description: "Append-only provenance ledger entry — every automator-driven write emits one @PROVENANCE record carrying the full attribution chain (src + method + confidence + hash + tokens + cost + model + approver), followed by a chained @STAMP. Distinct from inline @STAMP records (which carry per-write provenance into note frontmatter / pre-declaration position): @PROVENANCE is the ledger-shape ARCHIVE; inline @STAMP is the per-write CARRIER. They coexist.",
      requiredFields: ["target_type", "target_id", "ts", "src"],
      optionalFields: ["method", "confidence", "hash", "tokens", "cost_usd", "model", "approver", "details_json"],
      typedFields: { "ts": "ts", "confidence": "float", "tokens": "int", "cost_usd": "float" },
      fields: {
        "target_type": { type: "string", required: true, enum: ["note", "declaration", "yon-record", "meta-key", "vault", "mesh", "edge", "subscription", "registry"], description: "Kind of target the provenance attaches to", example: "note" },
        "target_id": { type: "string", required: true, description: "Identifier of the targeted entity — typically the vault-relative POSIX path for notes/declarations, or a rid for typed entities", example: "notes/2026-05-30-thought-yai-lyt.md" },
        "ts": { type: "ts", required: true, description: "ISO 8601 UTC timestamp the write occurred", example: "2026-05-30T14:30:00.000Z" },
        "src": { type: "string", required: true, description: "Who attribution — conventionally 'automator:<name>/v<ver>' (e.g. 'automator:metadata-filler/v0.1.0'); also accepts 'user:<handle>', 'system:lyt', 'agent:<name>'", example: "automator:metadata-filler/v0.1.0" },
        "method": { type: "string", required: false, description: "Archetype-ish method label — filler, rollup, ingest, ai-relay, byok, etc.", example: "filler" },
        "confidence": { type: "float", required: false, range: [0, 1], description: "Provenance confidence — 1.0 for deterministic writes, lower for LLM-attributed writes", example: "1.0" },
        "hash": { type: "string", required: false, description: "Content hash of the written payload — conventionally 'sha256:<hex>' (64 hex chars after the prefix)", example: "sha256:abc123def456…" },
        "tokens": { type: "int", required: false, range: [0, 10000000], description: "Tokens consumed by an LLM call that produced this write (0 or omitted for deterministic writes)", example: "0" },
        "cost_usd": { type: "float", required: false, range: [0, 1000], description: "USD cost of the LLM call that produced this write (0 or omitted for deterministic writes)", example: "0.0" },
        "model": { type: "string", required: false, description: "LLM model identifier that produced this write (omitted for deterministic writes)", example: "claude-opus-4-7" },
        "approver": { type: "string", required: false, description: "When the write required HIL approval (via @ESCALATE), the approver's rid is recorded here", example: "user:acme-handler" },
        "details_json": { type: "string", required: false, description: "JSON-encoded extra context (fields_changed, input_note_hash, mesh_context, etc.)", example: "{\"fields_changed\":[\"topic\",\"purpose\"]}" },
      },
    },
    ROTATION: {
      description: "Month-boundary rotation event — `lyt housekeep` emits one @ROTATION record into the FRESH current-month ledger after renaming the prior file into the archive subdirectory. Followed by a chained @STAMP. The rotated archive is sealed; the new file opens with @DOC + @META key=month | value=<to_month> + @ROTATION + @STAMP.",
      requiredFields: ["from_month", "to_month", "archived_path"],
      fields: {
        "from_month": { type: "string", required: true, description: "Month-key of the archived file — YYYY-MM (UTC)", example: "2026-04" },
        "to_month": { type: "string", required: true, description: "Month-key of the fresh current-month file — YYYY-MM (UTC); always > from_month", example: "2026-05" },
        "archived_path": { type: "string", required: true, description: "Absolute filesystem path where the prior current-month file was renamed — conventionally <vault>/.lyt/ledgers/<name>/<from_month>.yon", example: "C:/.../vault/.lyt/ledgers/audit/2026-04.yon" },
      },
    },
    MESH: {
      description: "Mesh declaration — a named group of vaults sharing a GitHub push target. Lives in the main vault's `.lyt/mesh.yon` as the source of truth for the mesh's identity, push target, and main vault binding. One record per mesh.",
      requiredFields: ["rid", "name", "main_vault_rid", "created_at"],
      optionalFields: ["push_target", "push_kind", "default_vault_update_cadence"],
      typedFields: { "created_at": "ts" },
      fields: {
        "rid": { type: "string", required: true, pattern: "^mesh:", description: "Mesh rid — UUIDv7 in canonical 8-4-4-4-12 dashed form, prefixed mesh:", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "name": { type: "string", required: true, description: "Mesh name — slug-safe segment (lowercase, [a-z0-9-]+, no Windows reserved names, no slashes; bare names, NOT owner/repo)", example: "personal" },
        "push_target": { type: "string", required: false, description: "GitHub push target — handle or org name. Omitted when the mesh was created with `--no-push`.", example: "acme-org" },
        "push_kind": { type: "string", required: false, enum: ["handle", "org"], description: "How push_target resolves — `handle` for personal GitHub accounts; `org` for GitHub organizations. Omitted under `--no-push`.", example: "handle" },
        "main_vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of this mesh's main vault. Structurally invariant — the main vault is named `main` and cannot be renamed.", example: "vault:0190abcd-1234-7000-8abc-def012345679" },
        "created_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when the mesh was provisioned via `lyt mesh init`", example: "2026-05-28T12:00:00Z" },
        "default_vault_update_cadence": { type: "string", required: false, description: "Mesh-level default sync cadence for home vaults that don't have their own @UPDATE_CADENCE record. Cron expression (5-field POSIX); applied per-vault as a fallback by subscribers' sync schedulers. Set via `lyt mesh update-cadence <mesh> --default-vault-cadence <spec>`. Omitted when no default is declared.", example: "0 9 * * 1" },
      },
    },
    MESH_HOME: {
      description: "Mesh home-vault membership — one record per vault the mesh OWNS (vs references via @MESH_EDGE / @MESH_SUBSCRIPTION). The mesh's main vault always appears as a @MESH_HOME; additional homes accumulate as `lyt vault init <mesh>/<name>` lands non-main vaults.",
      requiredFields: ["mesh_rid", "vault_rid", "vault_name"],
      fields: {
        "mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh this home belongs to (matches the parent @MESH.rid)", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of the home vault", example: "vault:0190abcd-1234-7000-8abc-def012345679" },
        "vault_name": { type: "string", required: true, description: "Human-facing vault name — the leaf segment after the mesh/slash (e.g. main, journal, lyt). The main vault always has name=main.", example: "main" },
      },
    },
    MESH_EDGE: {
      description: "Cross-mesh parent-child edge with rollup propagation — recorded in the REFERENCING mesh's mesh.yon (asymmetric awareness; the home mesh is unaware). Created by `lyt mesh add-edge --child <ref-vault> --parent <home-vault>`. Rollup propagates from child to parent.",
      requiredFields: ["ref_mesh_rid", "ref_vault_rid", "home_mesh_rid", "home_vault_rid", "kind"],
      fields: {
        "ref_mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh recording this edge (the referencing mesh — the one whose mesh.yon contains this record)", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "ref_vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of the home vault in ref_mesh_rid that acts as the PARENT in the parent-child relationship", example: "vault:0190abcd-1234-7000-8abc-def012345679" },
        "home_mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh that owns the CHILD vault (the home mesh of the referenced vault — may be the same as ref_mesh_rid for intra-mesh edges)", example: "mesh:0190abcd-1234-7000-8abc-defabc012345" },
        "home_vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of the CHILD vault (the referenced vault, owned by home_mesh_rid)", example: "vault:0190abcd-1234-7000-8abc-defabc012346" },
        "kind": { type: "string", required: true, enum: ["parent"], description: "Edge kind — `parent` in v1; future kinds reserved", example: "parent" },
      },
    },
    MESH_SUBSCRIPTION: {
      description: "Flat cross-mesh reference — recorded in the SUBSCRIBING mesh's mesh.yon. The subscribed vault becomes searchable in the subscribing mesh's mesh-scoped queries but NO rollup propagates (compare @MESH_EDGE). Created by `lyt mesh subscribe --vault <ref-vault>`.",
      requiredFields: ["mesh_rid", "external_vault_rid", "external_mesh_rid", "external_mesh_name"],
      fields: {
        "mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the subscribing mesh (the one whose mesh.yon contains this record)", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "external_vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of the subscribed vault (owned by external_mesh_rid)", example: "vault:0190abcd-1234-7000-8abc-defabc01234a" },
        "external_mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh that owns the subscribed vault", example: "mesh:0190abcd-1234-7000-8abc-defabc01234b" },
        "external_mesh_name": { type: "string", required: true, description: "Human-facing name of the external mesh — denormalized into the subscription record for fast list display without joining the registry", example: "acme" },
      },
    },
    MESH_PUBLIC: {
      description: "Publisher-declared discoverable metadata for a mesh advertised as a public mesh. Lives in the mesh's `.lyt/mesh.yon` alongside the @MESH header. Surfaced by `lyt mesh info` + `lyt mesh info --remote` (peek without cloning, via `gh api repos/{owner}/{mesh-main}/contents/.lyt/mesh.yon`). One record per mesh (the publish surface is a property of the mesh's identity). Absence = mesh is not publicly published; presence = publisher has run `lyt mesh publish`. Emitted in canonical key order for deterministic output.",
      requiredFields: ["mesh_rid", "description"],
      optionalFields: ["topics", "maintainer_contact", "maintainer_handle", "license_override", "accept_contributions", "contribution_url", "homepage_url", "chat_url", "created_at"],
      typedFields: { "accept_contributions": "bool", "created_at": "ts" },
      fields: {
        "mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh this public-metadata record belongs to (matches the parent @MESH.rid in the same mesh.yon)", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "description": { type: "string", required: true, description: "Short human-readable description of the mesh — what knowledge it publishes, who it's for. Surfaced in `lyt mesh info`.", example: "Acme's open-source documentation and team handbook" },
        "topics": { type: "string", required: false, description: "Comma-separated GitHub-style topic tags (publisher-declared; mirrors gh repo topics convention). Used for discovery filtering by `gh search repos --topic`.", example: "docs,handbook,open-source" },
        "maintainer_contact": { type: "string", required: false, description: "Maintainer contact — typically an email address, but may be any contact URL (mailto:, https://, etc.). Used by subscribers reporting issues with the published content.", example: "docs-team@acme.com" },
        "maintainer_handle": { type: "string", required: false, description: "Maintainer GitHub handle (or org name) — denormalised display label for the mesh's primary maintainer. May differ from @MESH.push_target (e.g. handle is the human; push_target is the org).", example: "acme-docs" },
        "license_override": { type: "string", required: false, description: "SPDX-like license identifier overriding the LICENSE file at the main vault's root. Used when the mesh has a content license distinct from the repo license (e.g. CC-BY-4.0 for content; Apache-2.0 for the surrounding tooling). Omitted when the LICENSE file is canonical.", example: "CC-BY-4.0" },
        "accept_contributions": { type: "bool", required: false, description: "Whether the publisher accepts external contributions via the standard OSS PR flow. Default semantics if omitted: true (contributions accepted on a best-effort basis). Explicit false signals a read-only publication posture.", example: "true" },
        "contribution_url": { type: "string", required: false, description: "URL to the publisher's contribution guidelines (typically CONTRIBUTING.md in the main vault repo). Required only when accept_contributions=true and contribution shape differs from standard OSS PR.", example: "https://github.com/acme/acme-public-main/CONTRIBUTING.md" },
        "homepage_url": { type: "string", required: false, description: "Publisher's main homepage URL — surfaced in `lyt mesh info`. Differs from the GitHub repo URL: homepage is the human-facing landing page.", example: "https://docs.acme.com" },
        "chat_url": { type: "string", required: false, description: "Publisher's primary chat/community channel URL — Discord, Slack, Matrix, IRC, etc. Used by subscribers seeking real-time help.", example: "https://discord.gg/acme-docs" },
        "created_at": { type: "ts", required: false, description: "ISO 8601 UTC timestamp when the mesh was first published (when `lyt mesh publish` first ran). Distinct from @MESH.created_at (which records when the mesh itself was provisioned). Defaults to mesh-publish run time when omitted at first write.", example: "2026-05-31T10:00:00.000Z" },
      },
    },
    UPDATE_CADENCE: {
      description: "Publisher-declared sync rhythm for a specific home vault in a public mesh. Lives in the mesh's `.lyt/mesh.yon`. Subscribers consume this record to drive their sync scheduler so they don't hammer GitHub polling. Zero-or-more records per mesh; sorted deterministically by vault_rid. Absence for a given vault = subscribers fall back to @MESH.default_vault_update_cadence (if set) or their local default. Cadence types: cron (POSIX 5-field), interval (seconds), on-demand (sync only when explicitly triggered).",
      requiredFields: ["vault_rid", "cadence_type"],
      optionalFields: ["cron", "interval_seconds", "timezone", "peak_hours", "on_demand_allowed"],
      typedFields: { "interval_seconds": "int", "on_demand_allowed": "bool" },
      fields: {
        "vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of the home vault this cadence applies to (matches a @MESH_HOME.vault_rid in the same mesh.yon)", example: "vault:0190abcd-1234-7000-8abc-def012345679" },
        "cadence_type": { type: "string", required: true, enum: ["cron", "interval", "on-demand"], description: "How the cadence is expressed — `cron` requires the cron field; `interval` requires interval_seconds; `on-demand` requires neither (subscribers sync only on explicit trigger).", example: "cron" },
        "cron": { type: "string", required: false, description: "POSIX 5-field cron expression (minute hour day-of-month month day-of-week). Required when cadence_type=cron; omitted otherwise.", example: "0 9 * * 1" },
        "interval_seconds": { type: "int", required: false, description: "Interval between syncs in seconds. Required when cadence_type=interval; omitted otherwise. Common values: 3600 (hourly), 86400 (daily), 604800 (weekly).", example: "86400" },
        "timezone": { type: "string", required: false, description: "IANA timezone identifier (e.g. Europe/Bucharest, America/New_York, UTC) — applied when interpreting the cron expression. Defaults to UTC when omitted.", example: "Europe/Bucharest" },
        "peak_hours": { type: "string", required: false, description: "Comma-separated list of local-time hours (0-23) during which the publisher prefers subscribers to sync. Advisory only — subscribers may ignore. Empty / omitted = no restriction.", example: "9,18" },
        "on_demand_allowed": { type: "bool", required: false, description: "Whether subscribers may force-sync outside the declared cadence window. Default semantics if omitted: true (subscribers free to override). Explicit false signals a strict cadence the publisher wants honored.", example: "true" },
      },
    },
    VAULT_HOME_MESH: {
      description: "Per-vault home-mesh assignment — declares which mesh OWNS this vault. Emitted into the vault's own `.lyt/vault.yon` alongside the @VAULT record. Companion to @MESH_HOME (which is the mesh-side view of the same binding, living in the home mesh's `.lyt/mesh.yon`). Emitted when `lyt vault init`, `lyt vault clone --to-mesh`, or `lyt vault move` assigns a vault to a mesh.",
      requiredFields: ["vault_rid", "mesh_rid", "mesh_name", "assigned_at"],
      typedFields: { "assigned_at": "ts" },
      fields: {
        "vault_rid": { type: "string", required: true, pattern: "^vault:", description: "Rid of this vault (matches the sibling @VAULT.rid in the same vault.yon file — round-trip self-reference)", example: "vault:0190abcd-1234-7000-8abc-def012345679" },
        "mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the mesh that owns this vault. Matches a @MESH.rid in some main vault's mesh.yon.", example: "mesh:0190abcd-1234-7000-8abc-def012345678" },
        "mesh_name": { type: "string", required: true, description: "Human-facing mesh name — denormalised cache so a vault can name its home mesh without a registry lookup", example: "personal" },
        "assigned_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when the vault was assigned to (or moved into) the home mesh", example: "2026-05-31T12:00:00.000Z" },
      },
    },
    FEDERATION: {
      description: "Per-handler GitHub federation declaration — the source of truth for `{handle}/lyt-federation`, the per-user repo anchoring which meshes a handler participates in. Surfaced to handlers as 'Your Pod'. One record per federation; lives at `~/lyt/federation/{handle}/federation.yon`.",
      requiredFields: ["rid", "handle", "visibility", "created_at"],
      typedFields: { "created_at": "ts" },
      fields: {
        "rid": { type: "string", required: true, pattern: "^fed:", description: "Federation rid — UUIDv7 in hex (no dashes), prefixed fed:. Stable across rebuilds.", example: "fed:0190abcd12347000abcdef0123456789" },
        "handle": { type: "string", required: true, description: "GitHub handle that owns this federation repo. The federation repo full name is conventionally `{handle}/lyt-federation`.", example: "acme-handler" },
        "visibility": { type: "string", required: true, enum: ["private", "public"], description: "GitHub repo visibility. Defaults to `private`; `public` is explicit opt-in.", example: "private" },
        "created_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when the federation was forged via `lyt federation init`", example: "2026-05-29T12:00:00Z" },
      },
    },
    FED_MESH: {
      description: "Per-federation joined-mesh record — one per mesh the handler participates in (own or join). Sorted deterministically by mesh_name (tiebreak by mesh_rid hex) in the emitted federation.yon.",
      requiredFields: ["fed_rid", "mesh_rid", "mesh_name", "push_target", "push_kind", "role", "added_at"],
      typedFields: { "added_at": "ts" },
      fields: {
        "fed_rid": { type: "string", required: true, pattern: "^fed:", description: "Rid of the federation this mesh-membership belongs to (matches the parent @FEDERATION.rid)", example: "fed:0190abcd12347000abcdef0123456789" },
        "mesh_rid": { type: "string", required: true, pattern: "^mesh:", description: "Rid of the joined mesh", example: "mesh:0190abcd12347000abcdef01234567aa" },
        "mesh_name": { type: "string", required: true, description: "Human-facing mesh name — denormalized for fast list display; primary sort key in deterministic output", example: "personal" },
        "push_target": { type: "string", required: true, description: "GitHub push target for the mesh's main vault repo (handle or org name)", example: "acme-org" },
        "push_kind": { type: "string", required: true, enum: ["handle", "org"], description: "How push_target resolves", example: "handle" },
        "role": { type: "string", required: true, enum: ["own", "join"], description: "Handler's relationship to this mesh — `own` if they hold push access to the mesh's main vault; `join` if they participate as a referencer/subscriber only", example: "own" },
        "added_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when this mesh joined the federation", example: "2026-05-29T12:05:00Z" },
      },
    },
    FED_AUTOMATOR: {
      description: "Per-federation automator registration — declares an automator visible across the handler's pod.",
      requiredFields: ["fed_rid", "automator_rid", "name", "version", "source", "added_at"],
      optionalFields: ["enabled"],
      typedFields: { "enabled": "bool", "added_at": "ts" },
      fields: {
        "fed_rid": { type: "string", required: true, pattern: "^fed:", description: "Rid of the federation owning this automator registration", example: "fed:0190abcd12347000abcdef0123456789" },
        "automator_rid": { type: "string", required: true, pattern: "^automator:", description: "Rid of the @AUTOMATOR record being registered (defined inline in a vault's `.lyt/automators/*.yon`)", example: "automator:metadata-filler" },
        "name": { type: "string", required: true, description: "Kebab-case automator name (matches the @AUTOMATOR.name field)", example: "metadata-filler" },
        "version": { type: "string", required: true, description: "Semver version of the registered automator", example: "0.1.0" },
        "source": { type: "string", required: true, enum: ["system", "user", "mesh", "marketplace"], description: "Provenance category — `system` (first-party signed_by=system:lyt); `user` (handler-authored); `mesh` (mesh-published); `marketplace` (third-party distribution channel)", example: "system" },
        "enabled": { type: "bool", required: false, description: "Whether the automator is currently active (default true)", example: "true" },
        "added_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when the automator joined the federation", example: "2026-05-29T12:10:00Z" },
      },
    },
    FED_PRIMER: {
      description: "Per-federation primer document pointer — declares a federation-scope primer (the agent-priming markdown that orients a fresh agent session to the handler's pod).",
      requiredFields: ["fed_rid", "primer_path", "scope", "generated_at"],
      optionalFields: ["cadence"],
      typedFields: { "generated_at": "ts" },
      fields: {
        "fed_rid": { type: "string", required: true, pattern: "^fed:", description: "Rid of the federation owning this primer reference", example: "fed:0190abcd12347000abcdef0123456789" },
        "primer_path": { type: "string", required: true, description: "POSIX path to the primer markdown relative to the federation-repo root", example: "primers/federation.md" },
        "scope": { type: "string", required: true, enum: ["vault", "mesh", "federation"], description: "Primer-coverage scope — `federation` is the cross-mesh handler-pod-wide variant; `mesh` is per-mesh; `vault` is per-vault", example: "federation" },
        "cadence": { type: "string", required: false, description: "Regeneration cadence — cron string, ISO-8601 duration interval, `manual`, or `event:<trigger>`. Drives primer-generator scheduling.", example: "0 6 * * *" },
        "generated_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp of last primer generation", example: "2026-05-29T06:00:00Z" },
      },
    },
    FED_CANVAS: {
      description: "Per-federation canvas pointer — declares a federation-scope JSON Canvas document (cross-mesh visual map of the handler's pod).",
      requiredFields: ["fed_rid", "canvas_rid", "title", "canvas_path", "created_at"],
      optionalFields: ["kind"],
      typedFields: { "created_at": "ts" },
      fields: {
        "fed_rid": { type: "string", required: true, pattern: "^fed:", description: "Rid of the federation owning this canvas reference", example: "fed:0190abcd12347000abcdef0123456789" },
        "canvas_rid": { type: "string", required: true, pattern: "^canvas:", description: "Rid of the canvas document — UUIDv7 prefixed canvas:", example: "canvas:0190abcd12347000abcdef0123456eee" },
        "title": { type: "string", required: true, description: "Human-facing canvas title shown in `lyt federation list --canvases` and similar surfaces", example: "Pod overview" },
        "canvas_path": { type: "string", required: true, description: "POSIX path to the .canvas file relative to the federation-repo root", example: "canvases/pod-overview.canvas" },
        "kind": { type: "string", required: false, enum: ["mesh-tree", "automator-graph", "lifecycle-flow", "custom"], description: "Canvas archetype — used for renderer hints + filter views; `custom` for handler-authored canvases", example: "mesh-tree" },
        "created_at": { type: "ts", required: true, description: "ISO 8601 UTC timestamp when the canvas was first registered with the federation", example: "2026-05-29T12:15:00Z" },
      },
    },
    LANE: {
      description: "Per-vault tag-frequency lane — a cluster of figments that share a source keyword (frontmatter tag). Emitted by `lyt vault rebuild-lanes` and by the lane-builder automator into `<vault>/.lyt/indexes/lanes.yon` (YON is the source of truth). Membership is materialised via companion @LANE_MEMBER records. Lanes use single-keyword-per-lane clustering (each tag with ≥threshold member notes becomes one @LANE with source_keywords=[tag]).",
      requiredFields: ["rid", "name", "source_keywords", "mem_count", "last_built"],
      typedFields: { "mem_count": "int", "last_built": "ts" },
      fields: {
        "rid": { type: "string", required: true, pattern: "^lane:", description: "Stable rid within a vault — `lane:<slugified-keyword>`. Slug = lowercase tag with non-alphanumeric runs replaced by `-`; e.g. `lane:software-design` for tag 'Software Design'.", example: "lane:thinking" },
        "name": { type: "string", required: true, description: "Human-readable lane name — the original tag string verbatim (preserves casing + spacing for display).", example: "Thinking" },
        "source_keywords": { type: "string", required: true, description: "Tags / keywords this lane clusters — emitted as a YON inline string-array (e.g. `source_keywords=[\"thinking\",\"writing\"]`). Single-element arrays (one lane per tag). Typed `string` at the schema level because the canonical type system enumerates only string|int|float|bool|ts atomics; composite shapes are described inline.", example: "[\"thinking\"]" },
        "mem_count": { type: "int", required: true, range: [0, 1000000], description: "Number of figments that belong to this lane. Equals the count of companion @LANE_MEMBER records.", example: "5" },
        "last_built": { type: "ts", required: true, description: "ISO 8601 UTC timestamp the lane was last rebuilt — caller-controlled so test rebuilds round-trip byte-identically.", example: "2026-05-31T14:00:00.000Z" },
      },
    },
    LANE_MEMBER: {
      description: "Membership row linking one figment to one @LANE — companion to @LANE. figment_rid is stored as a vault-relative POSIX path string. The companion cache schema in lyt.db uses TEXT for the figment_rid column accordingly.",
      requiredFields: ["lane_rid", "figment_rid"],
      fields: {
        "lane_rid": { type: "string", required: true, pattern: "^lane:", description: "Rid of the @LANE this membership belongs to.", example: "lane:thinking" },
        "figment_rid": { type: "string", required: true, description: "Vault-relative POSIX path to the figment markdown file.", example: "notes/2026-05-30-thought-tag-frequency.md" },
      },
    },
    ARC: {
      description: "Per-vault position-ordered narrative arc — a sequence of figments that share a narrative thread (e.g. a writing series, a project thread, a thinking arc). Emitted by `lyt vault rebuild-arcs` and by the arc-builder automator into `<vault>/.lyt/indexes/arcs.yon` (YON is the source of truth). Membership is materialised via companion @ARC_MEMBER records whose `position:int` field carries 1-based ordering. Detection is two-source: (1) frontmatter `arcs: [name1, name2, ...]` arrays — each figment declares which arcs it belongs to; (2) manual @ARC + @ARC_MEMBER records embedded in figment markdown bodies — handler-authored records win over frontmatter-derived auto-assignment for the same (arc, figment) pair. Unlike @LANE (clustered by tag frequency), @ARC is always explicit — there is no threshold.",
      requiredFields: ["rid", "name", "category", "last_touched"],
      typedFields: { "last_touched": "ts" },
      fields: {
        "rid": { type: "string", required: true, pattern: "^arc:", description: "Stable rid within a vault — `arc:<slugified-name>`. Slug = lowercase arc name with non-alphanumeric runs replaced by `-`; e.g. `arc:writing-the-paper` for name 'Writing the Paper'. Uses the same slugification as @LANE rids.", example: "arc:writing-the-paper" },
        "name": { type: "string", required: true, description: "Human-readable arc name — preserves casing + spacing for display. Frontmatter-declared arcs use the verbatim string from the `arcs:` array; manual @ARC declarations override with their explicit name (handler-customised display label).", example: "Writing the Paper" },
        "category": { type: "string", required: true, description: "Arc category — handler-supplied label that groups arcs by kind (e.g. 'writing', 'thinking', 'project', 'series'). Defaults to 'uncategorized' when no manual @ARC declaration provides a category. Multiple manual declarations with conflicting categories resolve last-by-deterministic-file-path-order, emitting a warning rather than an error.", example: "writing" },
        "last_touched": { type: "ts", required: true, description: "ISO 8601 UTC timestamp of the most-recently-modified member figment (max(mtime) across all members + any figment that declared the @ARC). Used by the primer-generator to surface recently-active arcs in cross-vault overviews.", example: "2026-05-31T14:00:00.000Z" },
      },
    },
    ARC_MEMBER: {
      description: "Membership row linking one figment to one @ARC at a specific 1-based position — companion to @ARC. figment_rid is stored as a vault-relative POSIX path string. Position resolution: manual @ARC_MEMBER records pinned in figment markdown bodies reserve their explicit positions; frontmatter-derived members auto-assign positions starting at 1 in deterministic file-path order, skipping reserved slots. Position collision (two distinct figments claiming the same (arc, position) pair via manual records) is a fatal build error. The companion cache schema in lyt.db uses TEXT for the figment_rid column accordingly.",
      requiredFields: ["arc_rid", "figment_rid", "position"],
      typedFields: { "position": "int" },
      fields: {
        "arc_rid": { type: "string", required: true, pattern: "^arc:", description: "Rid of the @ARC this membership belongs to.", example: "arc:writing-the-paper" },
        "figment_rid": { type: "string", required: true, description: "Vault-relative POSIX path to the figment markdown file.", example: "notes/2026-05-30-paper-intro.md" },
        "position": { type: "int", required: true, range: [1, 1000000], description: "1-based ordinal position within the @ARC. Manual records carry explicit positions; frontmatter-derived members auto-assign in file-path order, skipping reserved-manual slots.", example: "3" },
      },
    },
  },
};

